INSERT INTO changelog (title, body, created_at) VALUES ('Google: повідомлення, коли злітає доступ', 'Коли доступ до Google закінчується (тестовий режим Google — раз на ~7 днів), система одразу пише в Telegram з інструкцією, а не тільки в журнал. Поки не перепідключиш — нічний бекап бази на Диск і збереження фото з Telegram стоять. Назавжди прибрати 7-денне злітання: Google Cloud → OAuth consent screen → «Publish app».', datetime('now'));
